arguments.command:
cat > /tmp/askpass-ch.sh <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) echo "x-access-token" ;;
  *Password*) printf '%s' "$GITHUB_TOKEN" ;;
  *) echo "" ;;
esac
EOF
chmod +x /tmp/askpass-ch.sh
WT=/tmp/chandler-wt; GIT_ASKPASS=/tmp/askpass-ch.sh GIT_TERMINAL_PROMPT=0 git -C "$WT" push origin HEAD:friend/chandler 2>&1 | sed -E 's#(https?://)[^@]*@#\1REDACTED@#' | tail -5
